steps.vrml:
#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT EnvironmentalSensor : 3
COMPONENT PointingDeviceSensor : 1
COMPONENT Scripting : 1
COMPONENT Sound : 3
COMPONENT Text : 2

EXTERNPROTO Gadget [
  initializeOnly SFInt32  level
  initializeOnly SFString tag
  inputOutput    SFVec3f  offset
  outputOnly     SFInt32  result
  inputOnly      SFInt32  poke
]
"lib-a.wrl#Gadget"

DEF Plain Gadget { }

DEF Explicit Gadget {
  level 5
}

DEF Mirror Script {
  inputOnly SFInt32 fromPlain
  inputOnly SFInt32 fromExplicit
  inputOnly SFVec3f offsetPlain
  inputOnly SFVec3f offsetExplicit

  url "javascript:
function fromPlain (v) { print ('mirror plain ' + v); }
function fromExplicit (v) { print ('mirror explicit ' + v); }
function offsetPlain (v) { print ('mirror plain offset ' + v); }
function offsetExplicit (v) { print ('mirror explicit offset ' + v); }
"
}

DEF Clock TimeSensor {
  cycleInterval 0.5
  loop TRUE
}

DEF Driver Script {
  inputOnly      SFTime  tick
  outputOnly     SFInt32 poke_out
  outputOnly     SFVec3f offset_out
  initializeOnly SFInt32 n 1

  url "javascript:
function tick (t) {
  n = n + 1;
  print ('driver tick ' + n);
  poke_out = n;
  if (n == 2) offset_out = new SFVec3f (0, 0, 5);
}
"
}

ROUTE Clock.cycleTime TO Driver.tick
ROUTE Driver.poke_out TO Plain.poke
ROUTE Driver.poke_out TO Explicit.poke
ROUTE Driver.offset_out TO Explicit.set_offset
ROUTE Plain.result TO Mirror.fromPlain
ROUTE Explicit.result TO Mirror.fromExplicit
ROUTE Plain.offset_changed TO Mirror.offsetPlain
ROUTE Explicit.offset_changed TO Mirror.offsetExplicit

